#Completely Ai Generated by Claude Code 

import pytest

from cones import Cone, distance, filter_by_color, sort_by_distance, nearest


@pytest.fixture
def origin():
    """Reference point at (0, 0)."""
    return Cone("origin", 0, 0)


@pytest.fixture
def mixed_cones():
    """A fresh list of cones with mixed colors and distinct distances from the origin."""
    return [
        Cone("blue", 3, 4),      # distance 5
        Cone("yellow", 1, 0),    # distance 1
        Cone("blue", 6, 8),      # distance 10
        Cone("orange", 0, 2),    # distance 2
    ]


# ---------- Cone dataclass ----------

def test_cone_attributes():
    cone = Cone("blue", 1.5, -2.5)
    assert cone.color == "blue"
    assert cone.x == 1.5
    assert cone.y == -2.5


def test_cone_equality():
    assert Cone("blue", 1, 2) == Cone("blue", 1, 2)
    assert Cone("blue", 1, 2) != Cone("yellow", 1, 2)


# ---------- distance ----------

def test_distance_pythagorean_triple():
    assert distance(Cone("blue", 0, 0), Cone("blue", 3, 4)) == pytest.approx(5.0)


def test_distance_same_point_is_zero():
    cone = Cone("blue", 2, 2)
    assert distance(cone, cone) == 0


def test_distance_is_symmetric_and_handles_negatives():
    a = Cone("blue", -1, -1)
    b = Cone("yellow", 2, 3)
    assert distance(a, b) == pytest.approx(5.0)
    assert distance(a, b) == pytest.approx(distance(b, a))


# ---------- filter_by_color ----------

def test_filter_by_color_returns_only_matching(mixed_cones):
    result = filter_by_color(mixed_cones, "blue")
    assert len(result) == 2
    assert all(c.color == "blue" for c in result)


def test_filter_by_color_no_match_returns_empty_list(mixed_cones):
    assert filter_by_color(mixed_cones, "green") == []


def test_filter_by_color_empty_input():
    assert filter_by_color([], "blue") == []


def test_filter_by_color_does_not_modify_original(mixed_cones):
    original = list(mixed_cones)
    filter_by_color(mixed_cones, "blue")
    assert mixed_cones == original


# ---------- sort_by_distance ----------

def test_sort_by_distance_ascending(mixed_cones, origin):
    result = sort_by_distance(mixed_cones, origin)
    assert [distance(origin, c) for c in result] == pytest.approx([1, 2, 5, 10])
    assert [c.color for c in result] == ["yellow", "orange", "blue", "blue"]


def test_sort_by_distance_returns_new_list(mixed_cones, origin):
    original = list(mixed_cones)
    result = sort_by_distance(mixed_cones, origin)
    assert result is not mixed_cones
    assert mixed_cones == original  # input order untouched


def test_sort_by_distance_empty_list(origin):
    assert sort_by_distance([], origin) == []


def test_sort_by_distance_equidistant_cones(origin):
    """Ties: all four are distance 5 away; sorting must not crash and keeps input order (stable)."""
    cones = [
        Cone("a", 5, 0),
        Cone("b", 0, 5),
        Cone("c", -5, 0),
        Cone("d", 3, 4),
    ]
    result = sort_by_distance(cones, origin)
    assert len(result) == 4
    assert [c.color for c in result] == ["a", "b", "c", "d"]


def test_sort_by_distance_equidistant_mixed_with_others(origin):
    near = Cone("near", 1, 0)
    far = Cone("far", 20, 0)
    tie1 = Cone("tie1", 0, 5)
    tie2 = Cone("tie2", 5, 0)
    result = sort_by_distance([far, tie1, near, tie2], origin)
    assert result == [near, tie1, tie2, far]


# ---------- nearest ----------

def test_nearest_returns_closest(mixed_cones, origin):
    assert nearest(mixed_cones, origin) == Cone("yellow", 1, 0)


def test_nearest_empty_list_returns_none(origin):
    assert nearest([], origin) is None


def test_nearest_single_cone(origin):
    cone = Cone("blue", 7, 7)
    assert nearest([cone], origin) == cone


def test_nearest_equidistant_cones_is_predictable(origin):
    """Ties: returns the first tied cone from the input list, and never crashes."""
    first = Cone("first", 3, 4)
    second = Cone("second", -3, -4)
    third = Cone("third", 5, 0)
    assert nearest([first, second, third], origin) == first
    assert nearest([second, third, first], origin) == second


def test_nearest_with_non_origin_reference():
    reference = Cone("ref", 10, 10)
    cones = [Cone("a", 0, 0), Cone("b", 9, 9), Cone("c", 20, 20)]
    assert nearest(cones, reference) == Cone("b", 9, 9)